from collections import Counter
dp = [0] * 44
dp[0] = 1
dp[1] = 2
for i in range(2, 44):
	dp[i] = dp[i - 1] + dp[i - 2]

def solve(x, k, n):
	if k == 0:
		if x == 0:
			return 1
		else:
			return 0
	elif x == 0 or n == 0:
		return 0
	elif x >= 0 and x <= k * dp[n - 1]:
		return solve(x, k, n - 1) + solve(x - dp[n - 1], k - 1, n)
	return 0
T = int(input())
while T:
	T -= 1
	(x, k) = map(int, input().split())
	print(solve(x, k, 43))
